from apscheduler.schedulers.background import BackgroundScheduler
from moler.device import DeviceFactory
from taf.rfrl.utilities.tl_config import load_moler_configuration_from_tl


class MemoryMonitoring(object):
    """
    Class for collecting memory  - RAM usage for particular application
    """
    __instance = None
    __initialized = None

    def __new__(cls, *args, **kwargs):
        if MemoryMonitoring.__instance is None:
            MemoryMonitoring.__instance = super(MemoryMonitoring, cls).__new__(cls)

        return MemoryMonitoring.__instance

    def __init__(self):
        if self.__initialized:
            return
        self._data = []
        self._bgscheduler = BackgroundScheduler()
        MemoryMonitoring.__initialized = True

    def get_data(self):
        """
        Return collected data.
        :return: collected data
        """
        return self._data

    def get_average(self):
        """
        Calculate Average based on collected data
        :return: Average of memory usage
        """
        avg = round(sum([record['TOTAL'] for record in self._data]) / len(self._data), 2)
        return avg

    def start_memory_monitoring(self, device_name='UnixLocal', device_state='UNIX_LOCAL', application_name='firefox',
                                interval=2):
        """
        Start memory monitoring.
        :param device_name: moler device name
        :param device_state: device state on which memory will be checking
        :param application_name: App name
        :param interval: checking interval
        :return:
        """
        self._job = self._bgscheduler.add_job(func=self._collect_total_memory_usage_of_application,
                                              trigger='interval', seconds=interval,
                                              kwargs={'device_name': device_name,
                                                      'device_state': device_state,
                                                      'application_name': application_name})
        self._bgscheduler.start()

    def stop_memory_monitoring(self):
        """
        Stop memory monitoring.
        :return:
        """
        self._bgscheduler.shutdown(wait=False)

    def clear_collected_data(self):
        """
        Clear collected data.
        :return:
        """
        self._data = []

    @load_moler_configuration_from_tl()
    def _collect_total_memory_usage_of_application(self, device_name='UnixLocal', device_state='UNIX_LOCAL',
                                                   application_name='firefox'):
        device = DeviceFactory.get_device(name=device_name)
        device.goto_state(state=device_state)
        ps_options = r'-eo ppid,pid,user,%mem,%cpu,comm,cmd,rss,size | grep "{}\|%MEM" | grep -v grep'.\
            format(application_name)
        ps_cmd = device.get_cmd(cmd_name="ps",
                                cmd_params={"options": ps_options})

        processes = ps_cmd()
        ram = []
        for process in processes:
            ram.append(round(float(process['RSS']) / 1024, 2))

        self._data.append({'TOTAL': round(sum(ram), 2), 'VALUES': ram})
